command:
$readme = Join-Path $PWD 'README.md'
if (Test-Path $readme) {
    cat $readme | Select-Object -First 30
} else {
    Write-Host 'No README.md found'
}

$names = 'W32Time', 'Spooler', 'EventLog'
foreach ($n in $names) {
    $s = Get-Service -Name $n -ErrorAction SilentlyContinue
    if ($s) { "$($s.Name): $($s.Status)" } else { "$n: not found" }
}

$hosts = @('example.com', 'www.example.com')
$hosts | ForEach-Object {
    $r = Resolve-DnsName $_ -ErrorAction SilentlyContinue
    [pscustomobject]@{ Host = $_; Address = ($r.IPAddress -join ',') }
} | Format-Table -AutoSize

$headers = @{ Accept = 'application/json'; 'User-Agent' = 'dev-script/1.0' }
try {
    $r = Invoke-RestMethod -Uri 'https://example.com/api/status' -Headers $headers -Method Get -TimeoutSec 10
    $r | ConvertTo-Json -Depth 5
} catch {
    Write-Host "Request failed: $($_.Exception.Message)"
}

if (-not (Test-Path .\config.json)) {
    Copy-Item .\config.sample.json .\config.json -Verbose
} else {
    Write-Host 'config.json already exists, leaving it alone'
}

$branch = git rev-parse --abbrev-ref HEAD
Write-Host "Current branch: $branch"
if ($branch -eq 'main') {
    Write-Warning 'On main; create a feature branch first'
} else {
    git push -u origin $branch
}

$repos = Get-ChildItem $env:USERPROFILE\source\repos -Directory
foreach ($r in $repos) {
    if (Test-Path (Join-Path $r.FullName '.git')) {
        $b = git -C $r.FullName branch --show-current
        Write-Output "$($r.Name): $b"
    }
}

try {
    $resp = Invoke-RestMethod -Uri 'https://example.com/health' -TimeoutSec 5
    Write-Host "Healthy: $resp"
} catch {
    Write-Host "Health check failed: $($_.Exception.Message)"
    exit 1
}

$files = Get-ChildItem -Path . -Recurse -Include *.js,*.ts -Exclude node_modules
$total = 0
foreach ($f in $files) {
    $total += (Get-Content $f.FullName | Measure-Object -Line).Lines
}
Write-Host "Total lines: $total"

$port = 5000
$conn = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue
if ($conn) {
    $p = Get-Process -Id $conn.OwningProcess
    Write-Host "Port $port in use by $($p.ProcessName) (PID $($p.Id))"
} else {
    Write-Host "Port $port is free"
}

docker ps --format "table {{.Names}}\t{{.Status}}"
if ($LASTEXITCODE -ne 0) {
    Write-Host 'Docker is not running'
}

$jobs = 1..3 | ForEach-Object {
    Start-Job -ArgumentList $_ -ScriptBlock {
        param($n)
        Start-Sleep -Seconds $n
        "job $n done"
    }
}
$jobs | Wait-Job | Receive-Job

$ErrorActionPreference = 'Stop'
try {
    $data = Get-Content .\data.json -Raw | ConvertFrom-Json
    $data.items | Where-Object { $_.active } | ForEach-Object { $_.id }
} catch {
    Write-Error "Could not parse data.json: $_"
}

Get-ChildItem *.csproj -Recurse | ForEach-Object {
    [xml]$x = Get-Content $_.FullName
    $tf = $x.Project.PropertyGroup.TargetFramework | Select-Object -First 1
    [pscustomobject]@{ Project = $_.Name; Framework = $tf }
} | Format-Table -AutoSize
